WITH filtered AS (SELECT *, DATE_TRUNC('WEEK', launch_date) AS launch_date_period, COALESCE(brand, 'NONE') AS brand_clean FROM products WHERE SIZE(tags) > 2), kept_keys AS (SELECT supplier_id, category FROM filtered INTERSECT ALL SELECT supplier_id, category FROM products WHERE launch_date > '2023-07-01'), reconciled AS (SELECT s.* FROM filtered s INNER JOIN kept_keys k ON s.supplier_id = k.supplier_id AND s.category = k.category), enriched AS (SELECT *, AVG(price) OVER (PARTITION BY supplier_id ORDER BY CAST(launch_date_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS price_avg_30d, SUM(price) OVER (PARTITION BY category) AS category_sum_price, CORR(stock_qty, cost) OVER w_ordered AS corr_stock_qty_cost, STDDEV_SAMP(cost) OVER (PARTITION BY brand, category) AS brand_stddev_samp_cost, DENSE_RANK() OVER (ORDER BY cost NULLS LAST) AS cost_dense_rank FROM reconciled WINDOW w_ordered AS (PARTITION BY supplier_id, brand)), stats AS (SELECT category, CASE WHEN cost >= 620 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, COUNT_IF(brand = 'Initech') AS initech_events, SUM(cost) FILTER (WHERE category = 'Sports') AS sports_total_cost, MAX(price) FILTER (WHERE brand = 'Stark') AS stark_max_price FROM enriched GROUP BY GROUPING SETS ((category, CASE WHEN cost >= 620 THEN 'PREMIUM' ELSE 'STANDARD' END), (category), ()) HAVING stark_max_price >= 0) SELECT category, initech_events, stark_max_price, CASE WHEN category RLIKE '^(Fashion|Home)$' THEN 'EXTENDED' WHEN category RLIKE '^(Electronics|Sports)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS category_zone FROM stats ORDER BY category DESC;
